declare(strict_types=1);

function view_dashboard(): void {
    $today=local_now()->setTime(0,0);$tomorrow=$today->modify('+1 day');$start=utc_string($today);$end=utc_string($tomorrow);
    $stats=one("SELECT COUNT(*) AS total,SUM(status='pending') AS pending,SUM(status='confirmed') AS confirmed,SUM(status='completed') AS completed FROM bk_appointments WHERE starts_at>=? AND starts_at<? AND status<>'cancelled'",[$start,$end]);
    $month=utc_string($today->modify('first day of this month'));
    $revenue=rows("SELECT a.currency_code, SUM(CASE WHEN p.entry_type='refund' THEN -CAST(p.amount_minor AS SIGNED) ELSE p.amount_minor END) AS total FROM bk_payments p JOIN bk_appointments a ON a.id=p.appointment_id WHERE p.created_at>=? GROUP BY a.currency_code ORDER BY a.currency_code",[$month]);
    $upcoming=rows("SELECT a.*,s.name AS staff_name FROM bk_appointments a JOIN bk_staff s ON s.id=a.staff_id WHERE a.starts_at>=? AND a.status IN ('pending','confirmed') ORDER BY a.starts_at LIMIT 6",[utc_string(now_utc())]);
    $pending=(int)(one("SELECT COUNT(*) AS n FROM bk_appointments WHERE status='pending' AND starts_at>=?",[$start])['n']);
    admin_start('Overview','dashboard','A clear view of your day. A little room to plan ahead.'); ?>
<div class="overview-welcome"><div><span class="eyebrow">LET’S MAKE TODAY A GOOD ONE</span><h2>Hello, <?=e(explode(' ',require_user()['name'])[0])?> <span class="hello-dot">✦</span></h2><p><?=($stats['total'] ?? 0)?'You have '.(int)$stats['total'].' appointments on the calendar today.':'Your calendar has room for something good. Share your booking page to get started.'?></p></div><div class="welcome-art" aria-hidden="true"><div class="mini-calendar"><span><?=strtoupper($today->format('M'))?></span><strong><?=$today->format('j')?></strong><small><?=$today->format('l')?></small></div><span class="art-orb"><?=icon('check')?></span></div></div>
<div class="stats-grid"><article class="stat-card"><div><span>Appointments today</span><span class="stat-icon teal"><?=icon('calendar')?></span></div><strong><?=(int)($stats['total'] ?? 0)?></strong><small><?=e($today->format('l, j F'))?></small></article><article class="stat-card"><div><span>Awaiting confirmation</span><span class="stat-icon amber"><?=icon('clock')?></span></div><strong><?=$pending?></strong><small>Today and upcoming</small></article><article class="stat-card"><div><span>Completed today</span><span class="stat-icon blue"><?=icon('check')?></span></div><strong><?=(int)($stats['completed'] ?? 0)?></strong><small>Marked completed by you</small></article><article class="stat-card"><div><span>Net receipts this month</span><span class="stat-icon violet"><?=icon('money')?></span></div><?php if(!$revenue):?><strong class="stat-money"><?=e(money(0))?></strong><?php else:foreach($revenue as $r):?><strong class="stat-money"><?=e(money((int)$r['total'],$r['currency_code']))?></strong><?php endforeach;endif;?><small>Recorded payments less refunds</small></article></div>
<div class="overview-grid"><section class="panel chart-panel"><div class="panel-heading"><div><h2>The week at a glance</h2><p class="muted">Appointments over the next 7 days</p></div><span class="legend-dot">Bookings</span></div><?php $counts=[];for($i=0;$i<7;$i++){$d=$today->modify('+'.$i.' days');$counts[]=['label'=>$d->format('D'),'date'=>$d->format('j M'),'n'=>(int)one("SELECT COUNT(*) AS n FROM bk_appointments WHERE starts_at>=? AND starts_at<? AND status IN ('pending','confirmed','completed')",[utc_string($d),utc_string($d->modify('+1 day'))])['n']];}$max=max(1,...array_column($counts,'n'));?>
<svg class="week-chart" viewBox="0 0 560 205" role="img" aria-labelledby="chart-title"><title id="chart-title"><?=e(implode('; ',array_map(fn($c)=>$c['label'].' '.$c['date'].': '.$c['n'].' appointments',$counts)))?></title><?php for($i=0;$i<=3;$i++):$y=25+$i*45;?><line x1="22" y1="<?=$y?>" x2="548" y2="<?=$y?>" class="chart-grid"/><?php endfor;foreach($counts as $i=>$c):$x=40+$i*73;$height=$c['n']/$max*126;?><rect x="<?=$x?>" y="<?=170-$height?>" width="36" height="<?=$height?>" rx="6" class="chart-bar <?=$i===0?'chart-bar-today':''?>"/><text x="<?=$x+18?>" y="<?=max(19,158-$height)?>" text-anchor="middle" class="chart-count"><?=$c['n']?></text><text x="<?=$x+18?>" y="197" text-anchor="middle" class="chart-label"><?=$c['label']?></text><?php endforeach;?></svg></section><section class="share-card"><span class="share-icon"><?=icon('external')?></span><p class="eyebrow">YOUR DOOR IS ALWAYS OPEN</p><h2>A link to your<br>next booking.</h2><p>Add your booking link to your website, social profiles, or WhatsApp bio.</p><div class="booking-url"><?=e(parse_url(config()['app_url'],PHP_URL_HOST).parse_url(config()['app_url'],PHP_URL_PATH))?></div><button class="button button-light button-full" type="button" data-copy="<?=e(absolute_url('book'))?>"><?=icon('copy')?>Copy booking link</button></section></div>
<section class="panel table-panel"><div class="panel-heading"><div><h2>Coming up next</h2><p class="muted">Your next appointments, in order.</p></div><a class="text-link" href="<?=e(url('appointments'))?>">View all<?=icon('arrow')?></a></div><?php appointment_table($upcoming);?></section><?php admin_end();
}

function booking_filters(): array {
    $where=[];$params=[];$search=trim(get_string('q'));$status=get_string('status');$from=get_string('from');$to=get_string('to');
    if(strlen($search)>100)$search=substr($search,0,100);
    if($search!==''){$where[]='(a.client_name LIKE ? ESCAPE \'!\' OR a.client_phone LIKE ? ESCAPE \'!\' OR a.reference LIKE ? ESCAPE \'!\')';$term='%'.str_replace(['!','%','_'],['!!','!%','!_'],$search).'%';array_push($params,$term,$term,$term);}
    if(in_array($status,['pending','confirmed','completed','cancelled','no_show'],true)){$where[]='a.status=?';$params[]=$status;}
    if($from!==''){try{$d=parse_local($from,'00:00');$where[]='a.starts_at>=?';$params[]=utc_string($d);}catch(ValidationError){}}
    if($to!==''){try{$d=parse_local($to,'00:00')->modify('+1 day');$where[]='a.starts_at<?';$params[]=utc_string($d);}catch(ValidationError){}}
    return [$where?' WHERE '.implode(' AND ',$where):'',$params,['q'=>$search,'status'=>$status,'from'=>$from,'to'=>$to]];
}
function view_appointments(): void {
    [$where,$params,$f]=booking_filters();$total=(int)one('SELECT COUNT(*) AS n FROM bk_appointments a'.$where,$params)['n'];$pages=max(1,(int)ceil($total/20));$p=max(1,min($pages,(int)get_string('p','1')));$offset=($p-1)*20;
    $bookings=rows('SELECT a.*,s.name AS staff_name FROM bk_appointments a JOIN bk_staff s ON s.id=a.staff_id'.$where.' ORDER BY a.starts_at DESC,a.id DESC LIMIT 20 OFFSET '.$offset,$params);
    admin_start('Appointments','appointments','Every visit, every detail. Keep your calendar moving.'); ?>
<section class="panel table-panel"><form method="get" class="filters"><input type="hidden" name="page" value="appointments"><label class="search-field"><?=icon('search')?><input name="q" value="<?=e($f['q'])?>" placeholder="Search name, phone, reference" aria-label="Search bookings"></label><select name="status" aria-label="Booking status"><option value="">All statuses</option><?php foreach(['pending','confirmed','completed','cancelled','no_show'] as $s):?><option value="<?=$s?>" <?=$f['status']===$s?'selected':''?>><?=status_label($s)?></option><?php endforeach;?></select><input type="date" name="from" value="<?=e($f['from'])?>" aria-label="From date"><input type="date" name="to" value="<?=e($f['to'])?>" aria-label="To date"><button class="button button-small">Filter</button><a class="button button-small button-ghost" href="<?=e(url('export',$f+['csrf'=>csrf()]))?>">Export CSV</a></form><div class="table-caption"><strong><?=$total?> appointments</strong><a class="text-link" href="<?=e(url('appointments'))?>">Reset filters</a></div><?php appointment_table($bookings);?><div class="pagination"><span>Page <?=$p?> of <?=$pages?></span><div><?php if($p>1):?><a class="button button-small button-ghost" href="<?=e(url('appointments',$f+['p'=>$p-1]))?>">← Previous</a><?php endif;if($p<$pages):?><a class="button button-small button-ghost" href="<?=e(url('appointments',$f+['p'=>$p+1]))?>">Next →</a><?php endif;?></div></div></section><?php admin_end();
}

function view_appointment(): void {
    $b=one('SELECT a.*,s.name AS staff_name FROM bk_appointments a JOIN bk_staff s ON s.id=a.staff_id WHERE a.id=?',[(int)get_string('id')]);if(!$b){flash('Booking not found.','error');redirect('appointments');}
    $paid=payment_total((int)$b['id']);$payments=rows('SELECT * FROM bk_payments WHERE appointment_id=? ORDER BY created_at DESC,id DESC',[$b['id']]);admin_start('Appointment details','appointments',$b['reference'].' · Created '.local_date($b['created_at'])); ?>
<a class="back-link" href="<?=e(url('appointments'))?>">← All appointments</a><div class="detail-layout"><section class="panel"><div class="panel-heading"><div><span class="eyebrow"><?=e($b['reference'])?></span><h2><?=e($b['service_name'])?></h2></div><?=status_badge($b['status'])?></div><div class="appointment-hero"><span class="large-avatar"><?=e(short_name($b['client_name']))?></span><div><h2><?=e($b['client_name'])?></h2><p><?=e($b['client_phone'])?></p><?php if($b['client_email']):?><a href="mailto:<?=e($b['client_email'])?>"><?=e($b['client_email'])?></a><?php endif;?></div></div><dl class="detail-grid"><div><dt>Date</dt><dd><?=e(local_date($b['starts_at'],'l, j M Y'))?></dd></div><div><dt>Time</dt><dd><?=e(local_date($b['starts_at'],'g:i a'))?>–<?=e(local_date($b['ends_at'],'g:i a'))?></dd></div><div><dt>Team member</dt><dd><?=e($b['staff_name'])?></dd></div><div><dt>Duration</dt><dd><?=(int)$b['duration_minutes']?> minutes</dd></div></dl><?php if($b['notes']):?><div class="payment-note"><strong>Customer notes</strong><p><?=nl2br(e($b['notes']))?></p></div><?php endif;?><div class="appointment-actions"><?php if(in_array($b['status'],['pending','confirmed'],true)):?><a class="button button-ghost" href="<?=e(url('move',['id'=>$b['id']]))?>">Reschedule</a><?php endif;?><button type="button" class="button button-ghost" data-print>Print details</button></div><div class="status-actions"><?php $transitions=['pending'=>['confirmed','cancelled'],'confirmed'=>['completed','no_show','cancelled']];foreach($transitions[$b['status']] ?? [] as $status):?><form method="post" <?=$status==='cancelled'?'data-confirm="Cancel this appointment? This does not issue a refund."':''?>><?=csrf_field()?><input type="hidden" name="action" value="booking_status"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><input type="hidden" name="status" value="<?=$status?>"><button class="button button-small <?=$status==='cancelled'?'button-danger':'button-ghost'?>"><?=e(['confirmed'=>'Confirm booking','completed'=>'Mark completed','no_show'=>'Mark no-show','cancelled'=>'Cancel booking'][$status])?></button></form><?php endforeach;?></div></section><aside class="panel"><div class="panel-heading"><h2>Payment summary</h2><span class="stat-icon teal"><?=icon('money')?></span></div><dl class="receipt-money"><div><dt>Total</dt><dd><?=e(money((int)$b['price_minor'],$b['currency_code']))?></dd></div><div><dt>Net received</dt><dd><?=e(money($paid,$b['currency_code']))?></dd></div><div class="balance"><dt><?=$b['status']==='cancelled'?'Payment held':'Balance due'?></dt><dd><?=e(money($b['status']==='cancelled'?$paid:max(0,(int)$b['price_minor']-$paid),$b['currency_code']))?></dd></div></dl><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="payment_add"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><?php select_field('entry_type','Entry type',['payment'=>'Payment received','refund'=>'Refund given'],'payment');field('amount','Amount ('.$b['currency_code'].')',raw_amount(max(0,(int)$b['price_minor']-$paid)),'text');select_field('method','Method',['cash'=>'Cash','bank'=>'Bank transfer','easypaisa'=>'Easypaisa','jazzcash'=>'JazzCash','other'=>'Other'],'cash');field('note','Note / transfer reference','','text',false);?><button class="button button-full">Record entry</button><p class="small muted">Record only money you have received or refunded. This form does not transfer money.</p></form></aside></div><section class="panel table-panel"><div class="panel-heading"><h2>Payment history</h2><span class="small muted">Permanent entries for your records</span></div><?php if(!$payments):empty_state('No payments recorded','Record a payment after checking receipt.','money');else:?><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Type</th><th>Method</th><th>Note</th><th class="align-right">Amount</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e(local_date($p['created_at']))?></td><td><?=e(ucfirst($p['entry_type']))?></td><td><?=e(ucfirst($p['method']))?></td><td><?=e($p['note'])?></td><td class="align-right"><?=e(($p['entry_type']==='refund'?'−':'').money((int)$p['amount_minor'],$b['currency_code']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php admin_end();
}

