function view_account(): void {
    $u=require_user();admin_start('Your account','account','Keep your owner account up to date.'); ?>
<section class="panel account-panel"><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="account_save"><?php field('name','Your name',$u['name']);field('email','Login email',$u['email'],'email');field('current_password','Current password','','password');?><label class="field"><span>New password <small>optional</small></span><input type="password" name="new_password" autocomplete="new-password" minlength="12" maxlength="72"><small class="field-hint">Leave blank to keep it. Use 12–72 characters for a new password.</small></label><button class="button">Update account</button><p class="small muted">You’ll sign in again after saving. Other active owner sessions will be signed out.</p></form></section><?php admin_end();
}
function download_export(): void {
    if(!hash_equals(csrf(),get_string('csrf'))){http_response_code(403);echo 'Open Export CSV from your appointments page.';return;}
    [$where,$params]=booking_filters();$bookings=rows('SELECT a.*,s.name AS staff_name FROM bk_appointments a JOIN bk_staff s ON s.id=a.staff_id'.$where.' ORDER BY a.starts_at DESC LIMIT 5000',$params);
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="booknest-appointments-'.local_now()->format('Y-m-d').'.csv"');$stream=fopen('php://output','w');fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,['Reference','Customer','Phone','Email','Service','Team member','Date & time ('.setting('timezone').')','Duration (min)','Status','Currency','Total','Net paid','Notes'],',','"','');
    foreach($bookings as $b){$line=[$b['reference'],$b['client_name'],$b['client_phone'],$b['client_email'],$b['service_name'],$b['staff_name'],local_date($b['starts_at'],'Y-m-d H:i'),$b['duration_minutes'],$b['status'],$b['currency_code'],raw_amount((int)$b['price_minor']),raw_amount(payment_total((int)$b['id'])),$b['notes']];foreach($line as &$v){$v=(string)$v;if(preg_match('/^[\s]*[=+\-@]/u',$v))$v="'".$v;}unset($v);fputcsv($stream,$line,',','"','');}fclose($stream);
}
